import { useCallback, useEffect, useRef, useState } from 'react';

const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';

type UseSubscribeModalParams = {
  /** Whether the dialog is currently open. */
  isOpen: boolean;
  /** Called when the dialog should close (Escape). */
  onClose: () => void;
};

type UseSubscribeModalReturn = {
  /** False until after the first client render, so the portal is not created during SSR. */
  mounted: boolean;
  /** Attach to the dialog's <form> — bounds the Tab trap. */
  formRef: React.RefObject<HTMLFormElement>;
  /** Attach to the wrapper around the first field — its <input> receives initial focus. */
  firstFocusRef: React.RefObject<HTMLDivElement>;
};

/**
 * Dialog mechanics for the footer's subscribe modal: mount gating, focus save/restore,
 * body-scroll lock, and the Escape/Tab keyboard trap.
 *
 * Extracted from SubscribeModal per components.md's extract-to-hook threshold — four effects,
 * three of them with cleanup functions. None of it touches JSX, so the component keeps only its
 * markup and the recipe lookup. Behaviour is unchanged; the effect order and dependency arrays
 * are preserved exactly, because focus restore depends on running after the open-effect's
 * cleanup.
 *
 * @param params isOpen and the close callback
 * @returns the mount flag plus the two refs the dialog markup has to attach
 */
export const useSubscribeModal = ({ isOpen, onClose }: UseSubscribeModalParams): UseSubscribeModalReturn => {
  const [mounted, setMounted] = useState(false);
  const formRef = useRef<HTMLFormElement>(null);
  const firstFocusRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<Element | null>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Save the trigger element on open so focus can be restored on close
  useEffect(() => {
    if (isOpen) {
      triggerRef.current = document.activeElement;
      // Defer so the portal has rendered before we try to focus inside it
      const id = setTimeout(() => {
        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
        firstInput?.focus();
      }, 0);
      return () => clearTimeout(id);
    } else {
      // Return focus to the element that opened the modal
      if (triggerRef.current instanceof HTMLElement) {
        triggerRef.current.focus();
      }
    }
  }, [isOpen]);

  // Lock body scroll while modal is open
  useEffect(() => {
    if (!isOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, [isOpen]);

  // Keyboard: Escape to close, Tab trap within modal
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
        return;
      }
      if (e.key !== 'Tab' || !formRef.current) return;

      const focusable = Array.from(formRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
        (el) => !el.hasAttribute('disabled'),
      );

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last?.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first?.focus();
      }
    },
    [onClose],
  );

  useEffect(() => {
    if (!isOpen) return;
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, handleKeyDown]);

  return { mounted, formRef, firstFocusRef };
};

