      </svg>`;
    document.body.appendChild(host);
    const g = id => getComputedStyle(host.querySelector('#'+id)).fill;
    const out = { attrVar: g('attrVar'), styleVar: g('styleVar'), attrLit: g('attrLit') };
    host.remove();
    return out;
  });
  console.log('S9 SVG fill var() test:', JSON.stringify(varTest, null, 2));

  // Same test with a REAL theme token var, to confirm useToken is genuinely required
  const themeVarTest = await page.evaluate(() => {
    const root = getComputedStyle(document.documentElement);
    // find the chakra var for text.inverse
    const candidates = ['--chakra-colors-text-inverse', '--zimm-color-text-inverse'];
    const found = {};
    candidates.forEach(c => { found[c] = root.getPropertyValue(c).trim() || '(unset)'; });
    const host = document.createElement('div');
    host.innerHTML = `<svg width="10" height="10"><rect id="t" width="5" height="5" fill="var(--chakra-colors-text-inverse)"></rect></svg>`;
    document.body.appendChild(host);
    const computed = getComputedStyle(host.querySelector('#t')).fill;
    host.remove();
    return { vars: found, computedFillFromChakraVarAttr: computed };
  });
  console.log('S9 theme-var test:', JSON.stringify(themeVarTest, null, 2));

  // ---------- S10: paddingLeft baselines ----------
  const s10 = await page.evaluate(() => {
    const footer = document.querySelector('footer[role="contentinfo"]');
    const cols = [...footer.querySelectorAll('ul')].map(ul => {
      const col = ul.parentElement;
      const heading = col.querySelector('p');
      const items = [...ul.children];
      return {
        heading: heading ? heading.textContent.trim() : null,
        headingPaddingLeft: heading ? getComputedStyle(heading).paddingLeft : null,
        items: items.map(li => ({
          text: (li.textContent || '').trim().slice(0, 40),
          paddingLeft: getComputedStyle(li).paddingLeft,
          childTag: li.firstElementChild ? li.firstElementChild.tagName : null,
