/** TEMPORARY PROBE — Stage 1 validation of CLAIM S5. Deleted before this agent finishes. */
import React, { useState } from 'react';
import { describe, expect, test } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useSubscribeModal } from './useSubscribeModal';

const Harness = ({ withDisabled = false }: { withDisabled?: boolean }) => {
  const [open, setOpen] = useState(false);
  const { mounted, formRef, firstFocusRef } = useSubscribeModal({ isOpen: open, onClose: () => setOpen(false) });
  return (
    <div>
      <button onClick={() => setOpen(true)}>open</button>
      {mounted && open && (
        <div role="dialog">
          <form ref={formRef}>
            <div ref={firstFocusRef}>
              <input aria-label="first" />
            </div>
            <input aria-label="second" />
            {withDisabled && <button disabled>disabled-last</button>}
            <button type="submit">continue</button>
          </form>
        </div>
      )}
    </div>
  );
};

describe('PROBE S5', () => {
  test('userEvent.tab() respects a document-level keydown trap that preventDefaults', async () => {
    const u = userEvent.setup();
    render(<Harness />);
    await u.click(screen.getByText('open'));
    await new Promise((r) => setTimeout(r, 10));
    const first = screen.getByLabelText('first');
    const cont = screen.getByText('continue');
    expect(first).toHaveFocus();

    // forward wrap: focus last, Tab -> should land back on first (trap, not user-event's own move)
    cont.focus();
    expect(cont).toHaveFocus();
    await u.tab();
    expect(first).toHaveFocus();

    // shift wrap: focus first, Shift+Tab -> should land on last
    first.focus();
    await u.tab({ shift: true });
    expect(cont).toHaveFocus();
  });

  test('the disabled filter is observable: a disabled last control is skipped as `last`', async () => {
    const u = userEvent.setup();
    render(<Harness withDisabled />);
    await u.click(screen.getByText('open'));
    await new Promise((r) => setTimeout(r, 10));
    const first = screen.getByLabelText('first');
    const cont = screen.getByText('continue');
    first.focus();
    await u.tab({ shift: true });
    // if the disabled button were counted, `last` would be it and focus would go nowhere useful
    expect(cont).toHaveFocus();
  });

  test('body-scroll lock: overflow is hidden while open and restored on close', async () => {
    const u = userEvent.setup();
    document.body.style.overflow = 'scroll'; // pre-existing value the hook must restore
    render(<Harness />);
    expect(document.body.style.overflow).toBe('scroll');
    await u.click(screen.getByText('open'));
    expect(document.body.style.overflow).toBe('hidden');
    await u.keyboard('{Escape}');
    expect(document.body.style.overflow).toBe('scroll');
    document.body.style.overflow = '';
  });
});
EOF
