import userEvent from '@testing-library/user-event';

// Identical markup, NO trap installed. If userEvent.tab() already wrapped last->first on its
// own, the S5 probe would pass without the hook and prove nothing.
const NoTrap = () => (
  <div>
    <button>open</button>
    <div role="dialog">
      <form>
        <input aria-label="first" />
        <input aria-label="second" />
        <button type="submit">continue</button>
      </form>
    </div>
  </div>
);

describe('PROBE S5 mutation control', () => {
  test('without the trap, Tab from the last control does NOT wrap to the first', async () => {
    const u = userEvent.setup();
    render(<NoTrap />);
    const first = screen.getByLabelText('first');
    const cont = screen.getByText('continue');
    cont.focus();
    await u.tab();
    expect(first).not.toHaveFocus();
    // eslint-disable-next-line no-console
    console.log('   [mutation control] focus after unTrapped Tab ->', document.activeElement?.outerHTML?.slice(0, 60) ?? String(document.activeElement));
  });

  test('without the trap, Shift+Tab from the first control does NOT wrap to the last', async () => {
    const u = userEvent.setup();
    render(<NoTrap />);
    const first = screen.getByLabelText('first');
    const cont = screen.getByText('continue');
    first.focus();
    await u.tab({ shift: true });
    expect(cont).not.toHaveFocus();
    // eslint-disable-next-line no-console
    console.log('   [mutation control] focus after unTrapped Shift+Tab ->', document.activeElement?.outerHTML?.slice(0, 60) ?? String(document.activeElement));
  });
});
